INSERT INTO metric_definitions (metric_key, version, label, surface, unit, confidence, formula, session_basis, basis_label, grains, direction, comparison_mode, treatment, source_tables, effective_from, effective_to, change_note, created_at) VALUES
  ('direct_sessions_shopify', 1, 'Direct sessions', 'acquisition', 'count', 'measured', 'Σ Shopify sessions whose referrer bucket is direct', 'shopify', 'Shopify sessions', '["week"]', 'higher_better', 'drop_day', 'Shopify''s own referrer bucket, not a GA4 channel group. `social` counts paid and organic social together, so it is traffic from social, not organic demand on its own. Direct also catches sessions that arrive with no referrer at all, which includes in-app browsers, so it is a ceiling on people who came looking for the brand.', '["fact_session_daily"]', '1970-01-04', NULL, 'v1: added because the GA4 demand block has no data source and never had one.', '2026-09-12T00:00:00Z'),
  ('search_sessions_shopify', 1, 'Search sessions', 'acquisition', 'count', 'measured', 'Σ Shopify sessions whose referrer bucket is search', 'shopify', 'Shopify sessions', '["week"]', 'higher_better', 'drop_day', 'Shopify''s own referrer bucket, not a GA4 channel group. `social` counts paid and organic social together, so it is traffic from social, not organic demand on its own.', '["fact_session_daily"]', '1970-01-04', NULL, 'v1: added because the GA4 demand block has no data source and never had one.', '2026-09-12T00:00:00Z'),
  ('social_sessions_shopify', 1, 'Social sessions', 'acquisition', 'count', 'measured', 'Σ Shopify sessions whose referrer bucket is social', 'shopify', 'Shopify sessions', '["week"]', 'neutral', 'none', 'Shopify''s own referrer bucket, not a GA4 channel group. `social` counts paid and organic social together, so it is traffic from social, not organic demand on its own. It rises with ad spend, so it is not a demand signal on its own — read it against direct and search.', '["fact_session_daily"]', '1970-01-04', NULL, 'v1: added because the GA4 demand block has no data source and never had one.', '2026-09-12T00:00:00Z'),
  ('unpaid_session_share_shopify', 1, 'Non-social session share', 'acquisition', 'ratio', 'measured', '(sessions − social sessions) ÷ sessions', 'shopify', 'Shopify sessions', '["week"]', 'higher_better', 'drop_day', 'How much of the week''s traffic did not come through social. A proxy for demand that does not depend on spend, and a crude one: paid traffic that loses its referrer lands in direct.', '["fact_session_daily"]', '1970-01-04', NULL, 'v1: added because the GA4 demand block has no data source and never had one.', '2026-09-12T00:00:00Z');
